509:   /* ------------------------------------------------------------
510:      Hotspots, walking & interaction
511:      ------------------------------------------------------------ */
512:   function activeHotspots() {
513:     const sc = currentScene();
514:     if (!sc) return [];
515:     return sc.hotspots.filter((h) => !h.cond || h.cond(S));
516:   }
517: 
518:   function blockedAt(x, y, pad) {
519:     const sc = currentScene();
520:     if (!sc) return false;
521:     pad = pad == null ? 10 : pad;
522:     for (let i = 0; i < sc.blockers.length; i++) {
523:       if (U.pointInRect(sc.blockers[i], x, y, pad)) return true;
524:     }
525:     return false;
526:   }
527: 
528:   function hotspotApproach(h) {
529:     const sc = currentScene();
530:     if (!sc || !S) return { x: h.x, y: h.y };
531:     const walk = sc.walk;
532:     const r = h.r || 70;
533:     const radii = [r + 24, r + 58, r + 100, r + 150, r + 210];
534:     let best = null;
535:     let bestD = Infinity;
536:     for (let ri = 0; ri < radii.length; ri++) {
537:       const rad = radii[ri];
538:       for (let i = 0; i < 20; i++) {
539:         const a = (i / 20) * TAU;
540:         const x = clamp(h.x + Math.cos(a) * rad, walk.x + 18, walk.x + walk.w - 18);
541:         const y = clamp(h.y + Math.sin(a) * rad, walk.y + 18, walk.y + walk.h - 18);
542:         if (blockedAt(x, y, 12)) continue;
543:         const d = dist(S.player.x, S.player.y, x, y);
544:         if (d < bestD) {
545:           bestD = d;
546:           best = { x, y };
547:         }
548:       }
549:     }
550:     if (best) return best;
551:     return {
552:       x: clamp(h.x, walk.x + 18, walk.x + walk.w - 18),
553:       y: clamp(h.y, walk.y + 18, walk.y + walk.h - 18),
554:     };
555:   }
556: 
557:   function nearestHotspot() {
558:     const list = activeHotspots();
559:     let best = null;
560:     let bestD = Infinity;
561:     let bestAp = null;
562:     for (let i = 0; i < list.length; i++) {
563:       const h = list[i];
564:       const ap = hotspotApproach(h);
565:       const d = Math.min(dist(S.player.x, S.player.y, ap.x, ap.y), dist(S.player.x, S.player.y, h.x, h.y));
566:       if (d < bestD) {
567:         bestD = d;
568:         best = h;
569:         bestAp = ap;
570:       }
571:     }
572:     return bestD < 72 ? { h: best, ap: bestAp } : null;
573:   }
