595:   function interactWith(h) {
596:     if (!h || !S) return;
597:     const ap = hotspotApproach(h);
598:     const closeEnough = dist(S.player.x, S.player.y, ap.x, ap.y) < 72 || dist(S.player.x, S.player.y, h.x, h.y) < 76;
599:     if (closeEnough) {
600:       doAction(h);
601:     } else {
602:       walkTarget = { x: ap.x, y: ap.y };
603:       pendingHotspot = h;
604:       hide($('prompt'));
605:     }
