608:   function tapAt(sx, sy) {
609:     if (!S) return;
610:     const wx = sx / cam.scale + cam.x;
611:     const wy = sy / cam.scale + cam.y;
612:     const list = activeHotspots();
613:     for (let i = 0; i < list.length; i++) {
614:       const h = list[i];
615:       const rr = Math.max(32, (h.r || 70) * 0.95);
616:       if (dist(wx, wy, h.x, h.y) < rr) {
617:         interactWith(h);
618:         return;
619:       }
620:     }
621:     const walk = currentScene().walk;
622:     if (!U.pointInRect(walk, wx, wy, 0)) return;
623:     let tx = clamp(wx, walk.x + 14, walk.x + walk.w - 14);
624:     let ty = clamp(wy, walk.y + 14, walk.y + walk.h - 14);
625:     if (blockedAt(tx, ty, 11)) {
626:       let found = false;
627:       for (let rad = 24; rad <= 140 && !found; rad += 22) {
628:         for (let i = 0; i < 16 && !found; i++) {
629:           const a = (i / 16) * TAU;
630:           const nx = clamp(tx + Math.cos(a) * rad, walk.x + 14, walk.x + walk.w - 14);
631:           const ny = clamp(ty + Math.sin(a) * rad, walk.y + 14, walk.y + walk.h - 14);
632:           if (!blockedAt(nx, ny, 11)) {
633:             tx = nx;
634:             ty = ny;
635:             found = true;
636:           }
637:         }
638:       }
639:     }
640:     walkTarget = { x: tx, y: ty };
641:     pendingHotspot = null;
642:   }
643: 
644:   function movePlayer(dx, dy) {
645:     if (!S) return;
646:     const sc = currentScene();
647:     const walk = sc.walk;
648:     const p = S.player;
649:     const nx = clamp(p.x + dx, walk.x + 12, walk.x + walk.w - 12);
650:     if (!blockedAt(nx, p.y, 10)) p.x = nx;
651:     const ny = clamp(p.y + dy, walk.y + 12, walk.y + walk.h - 12);
652:     if (!blockedAt(p.x, ny, 10)) p.y = ny;
653:   }
