660:   function update(dt) {
661:     if (!S) return;
662:     S.playtime += dt;
663:     const sc = currentScene();
664:     let vx = 0;
665:     let vy = 0;
666: 
667:     if (keys['w'] || keys['arrowup']) vy -= 1;
668:     if (keys['s'] || keys['arrowdown']) vy += 1;
669:     if (keys['a'] || keys['arrowleft']) vx -= 1;
670:     if (keys['d'] || keys['arrowright']) vx += 1;
671: 
672:     if (joystickVec && Math.hypot(joystickVec.x, joystickVec.y) > 0.16) {
673:       vx = joystickVec.x;
674:       vy = joystickVec.y;
675:     }
676: 
677:     if (vx || vy) {
678:       walkTarget = null;
679:       pendingHotspot = null;
680:       const len = Math.hypot(vx, vy) || 1;
681:       const nx = vx / len;
682:       const ny = vy / len;
683:       S.player.dir = faceVector(nx, ny);
684:       movePlayer(nx * 178 * dt, ny * 178 * dt);
685:       playerWalking = true;
686:       playerPhase += dt * 9.4;
687:       stepClock -= dt;
688:       if (stepClock <= 0) {
689:         AUDIO.step(sc.surface);
690:         stepClock = 0.35;
691:       }
692:     } else if (walkTarget) {
693:       const dx = walkTarget.x - S.player.x;
694:       const dy = walkTarget.y - S.player.y;
695:       const d = Math.hypot(dx, dy);
696:       if (d < 5) {
697:         S.player.x = walkTarget.x;
698:         S.player.y = walkTarget.y;
699:         walkTarget = null;
700:         playerWalking = false;
701:         if (pendingHotspot) {
702:           const h = pendingHotspot;
703:           pendingHotspot = null;
704:           doAction(h);
705:         }
706:       } else {
707:         S.player.dir = faceVector(dx, dy);
708:         movePlayer((dx / d) * 178 * dt, (dy / d) * 178 * dt);
709:         playerWalking = true;
710:         playerPhase += dt * 9.4;
711:         stepClock -= dt;
712:         if (stepClock <= 0) {
713:           AUDIO.step(sc.surface);
714:           stepClock = 0.35;
715:         }
716:       }
717:     } else {
718:       playerWalking = false;
719:       stepClock = 0;
720:     }
721: 
722:     updateCamera(dt, false);
723: 
724:     autosaveClock += dt;
725:     if (autosaveClock > 22) {
726:       autosaveClock = 0;
727:       saveNow(false);
728:     }
729:   }
