964:     if (st.lineIndex >= lines.length) st.lineIndex = lines.length - 1;
965:     const text = lines[st.lineIndex];
966:     const chars = Array.from(String(text));
967:     const speed = Math.max(10, 44 * settings.textSpeed);
968:     st.typing = true;
969:     st.shown = 0;
970:     st.full = chars;
971:     st.timer = null;
972:     $('dlgText').textContent = '';
973:     $('dlgText').classList.toggle('narration', !st.node.speaker);
974:     $('dlgHint').textContent = 'click, or press space';
975:     let last = performance.now();
976:     const tick = () => {
977:       if (!dialogueState || dialogueState !== st || !st.typing) return;
978:       const now = performance.now();
979:       const add = Math.max(1, Math.floor(((now - last) / 1000) * speed));
980:       last = now;
981:       st.shown = Math.min(chars.length, st.shown + add);
982:       $('dlgText').textContent = chars.slice(0, st.shown).join('');
983:       if (st.shown >= chars.length) {
984:         st.typing = false;
985:         lineDone();
986:       } else {
987:         st.timer = setTimeout(tick, 16);
988:       }
989:     };
990:     st.timer = setTimeout(tick, 18);
