1239:   function inspectClick(e) {
1240:     if (!inspectState) return;
1241:     const c = $('inspectCanvas');
1242:     const rect = c.getBoundingClientRect();
1243:     const x = ((e.clientX - rect.left) / rect.width) * 900;
1244:     const y = ((e.clientY - rect.top) / rect.height) * 620;
1245:     const side = currentInspectSide();
1246:     let found = null;
1247:     let foundD = Infinity;
1248:     inspectState.obj.details.forEach((detail) => {
1249:       if (detail.side && detail.side !== side) return;
1250:       if (isDetailDiscovered(detail)) return;
1251:       const dx = detail.x * 900;
1252:       const dy = detail.y * 620;
1253:       const rr = Math.max(30, detail.r * Math.min(900, 620));
1254:       const d = dist(x, y, dx, dy);
1255:       if (d < rr && d < foundD) {
1256:         foundD = d;
1257:         found = detail;
1258:       }
1259:     });
1260:     if (found) discoverDetail(found);
1261:   }
