1263:   function renderInspect() {
1264:     if (!inspectState) return;
1265:     const c = $('inspectCanvas');
1266:     const g = c.getContext('2d');
1267:     const W = 900;
1268:     const H = 620;
1269:     if (inspectState.targetAngle != null) {
1270:       inspectState.angle = U.damp(inspectState.angle, inspectState.targetAngle, 12, dtGlobal);
1271:       if (Math.abs(inspectState.angle - inspectState.targetAngle) < 0.008) {
1272:         inspectState.angle = inspectState.targetAngle;
1273:         inspectState.targetAngle = null;
1274:       }
1275:     }
1276:     g.setTransform(1.5, 0, 0, 1.5, 0, 0);
1277:     g.clearRect(0, 0, W, H);
1278:     A.drawObject(g, inspectState.obj.id, W, H, { angle: inspectState.angle, t: tGlobal });
1279:     const side = currentInspectSide();
1280:     inspectState.obj.details.forEach((detail) => {
1281:       if (detail.side && detail.side !== side) return;
