327: /* board */
328: .board-frame{width:min(1220px,97vw);height:min(800px,94vh);background:linear-gradient(160deg,#222d2b,#141d1d);
329:   border:1px solid rgba(200,164,102,.25);box-shadow:var(--shadow);display:flex;flex-direction:column;overflow:hidden}
330: .board-frame .panel-head{border-bottom:1px solid rgba(200,164,102,.12);padding:20px 26px 15px}
331: .board-frame .panel-head h2{color:#efe3cc}
332: .board-frame .panel-head .eyebrow{color:var(--gold)}
333: .board-frame .icon-btn{border-color:rgba(200,164,102,.25);color:#c0b198}
334: .board-frame .icon-btn:hover{background:rgba(200,164,102,.1);color:#f1e5cf}
335: .board-head-actions{display:flex;align-items:center;gap:20px}
336: .board-frame .text-btn{color:var(--gold)}
337: .board-frame .text-btn:hover{color:#f1e5cf;border-color:#f1e5cf}
338: .board-main{display:flex;flex:1;min-height:0}
339: .board-canvas{flex:1;position:relative;margin:18px;overflow:hidden;border:1px solid rgba(200,164,102,.13);
340:   background:
341:    radial-gradient(ellipse at 30% 20%,rgba(226,169,95,.07),transparent 55%),
342:    radial-gradient(ellipse at 70% 80%,rgba(80,120,110,.08),transparent 60%),
343:    repeating-linear-gradient(45deg,rgba(255,255,255,.012) 0 2px,transparent 2px 4px),
344:    linear-gradient(140deg,#26322f,#1a2523 60%,#202c29);
345:   touch-action:none}
346: .board-canvas::after{content:"";position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 70px rgba(0,0,0,.45)}
347: #boardLines{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:1}
348: #boardCards{position:absolute;inset:0;z-index:2}
349: .board-empty{position:absolute;inset:0;display:grid;place-items:center;text-align:center;padding:40px;font-family:var(--serif);font-style:italic;
350:   color:#8e9a91;font-size:16px;pointer-events:none}
351: .clue-card{position:absolute;width:142px;min-height:88px;padding:11px 12px 9px;background:linear-gradient(160deg,#efe4cd,#dfcfb0);
352:   border:1px solid rgba(60,48,30,.35);box-shadow:0 8px 22px rgba(0,0,0,.35);cursor:grab;touch-action:none;user-select:none;
353:   transition:box-shadow .2s,transform .12s;transform:translate(-50%,-50%)}
354: .clue-card::before{content:"";position:absolute;top:5px;left:50%;transform:translateX(-50%);width:6px;height:6px;border-radius:50%;
355:   background:radial-gradient(circle at 35% 35%,#e9c37d,#8f6b31);box-shadow:0 1px 2px rgba(0,0,0,.4)}
356: .clue-card:hover{box-shadow:0 12px 30px rgba(0,0,0,.45)}
357: .clue-card.selected{outline:2px solid var(--amber);outline-offset:2px;transform:translate(-50%,-50%) scale(1.03)}
358: .clue-card.linked{box-shadow:0 8px 22px rgba(0,0,0,.35),0 0 0 1px rgba(168,70,60,.35)}
359: .clue-card.dragging{cursor:grabbing;box-shadow:0 18px 40px rgba(0,0,0,.55);z-index:5;transform:translate(-50%,-50%) scale(1.04)}
360: .clue-card .cc-kicker{font-size:6.5px;letter-spacing:.17em;text-transform:uppercase;color:#967b4e;margin-top:3px}
361: .clue-card .cc-title{font-family:var(--serif);font-size:15.5px;line-height:1.12;color:#31291d;margin-top:3px}
362: .clue-card .cc-sub{font-size:8.5px;line-height:1.3;color:#7d6c51;margin-top:4px}
363: .clue-card.wrong{animation:wrongShake .4s ease}
364: @keyframes wrongShake{0%,100%{margin-left:0}20%{margin-left:-6px}40%{margin-left:6px}60%{margin-left:-4px}80%{margin-left:4px}}
365: .board-side{width:290px;flex:none;padding:20px 22px;border-left:1px solid rgba(200,164,102,.12);overflow-y:auto;scrollbar-width:thin}
366: .board-instruction{font-family:var(--serif);font-style:italic;font-size:15px;line-height:1.45;color:#c8baa3;margin-bottom:16px}
367: .deductions{display:flex;flex-direction:column;gap:8px}
368: .deduction{padding:10px 12px;border-left:1px solid rgba(200,164,102,.18);background:rgba(255,255,255,.015)}
369: .deduction.found{border-left-color:var(--amber);background:linear-gradient(90deg,rgba(226,169,95,.09),transparent)}
370: .deduction h4{font-family:var(--serif);font-size:15px;color:#9c9282;font-weight:400;line-height:1.2}
371: .deduction.found h4{color:#f0e4ce}
372: .deduction p{font-family:var(--serif);font-size:12.5px;line-height:1.4;color:#8e8372;margin-top:3px;display:none}
373: .deduction.found p{display:block;color:#bcae97}
374: .deduction .d-mark{font-size:8px;letter-spacing:.14em;text-transform:uppercase;color:var(--gold);opacity:.6;display:block;margin-bottom:2px}
375: .board-progress{margin-top:18px;padding-top:14px;border-top:1px solid rgba(200,164,102,.14);font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:#a99c86}
376: .board-progress strong{color:var(--amber);font-weight:500}
377: .board-to-journal{margin-top:16px}
