379: /* decision */
380: .decision{background:radial-gradient(ellipse at 50% 35%,rgba(20,28,28,.75),rgba(4,7,8,.97));backdrop-filter:blur(8px)}
381: .decision-frame{width:min(980px,94vw);text-align:center;position:relative}
382: .decision-frame .eyebrow{color:var(--gold)}
383: .decision-frame h2{font-size:clamp(32px,4vw,50px);color:#f0e4ce;margin:8px 0 8px}
384: .decision-lead{font-family:var(--serif);font-style:italic;font-size:16px;color:#b8ab94;max-width:560px;margin:0 auto}
385: .decision-object{height:180px;margin:10px auto 4px;position:relative}
386: #decisionCanvas{height:100%;width:auto;max-width:100%;filter:drop-shadow(0 30px 40px rgba(0,0,0,.5))}
387: .decision-choices{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:10px;text-align:left}
388: .decision-choice{padding:20px 22px;border:1px solid rgba(200,164,102,.22);background:rgba(10,17,18,.5);transition:.25s;position:relative;overflow:hidden}
389: .decision-choice:hover{border-color:rgba(226,169,95,.65);background:rgba(226,169,95,.07);transform:translateY(-2px)}
390: .choice-kicker{display:block;font-size:8px;letter-spacing:.22em;text-transform:uppercase;color:var(--gold);margin-bottom:7px}
391: .choice-title{display:block;font-family:var(--serif);font-size:21px;line-height:1.2;color:#f1e5cf}
392: .choice-note{display:block;font-family:var(--serif);font-style:italic;font-size:13.5px;line-height:1.4;color:#a99c86;margin-top:7px}
393: .decision-cancel{margin-top:20px;color:#8e8372;border-color:transparent}
394: .decision-cancel:hover{color:#d8cbb4}
