426: /* settings */
427: .settings-frame{width:min(620px,94vw);max-height:92vh;background:linear-gradient(160deg,#eee1c9,#e0cfb0);border:1px solid rgba(200,164,102,.5);
428:   box-shadow:var(--shadow);display:flex;flex-direction:column;overflow:hidden}
429: .settings-body{padding:8px 32px 30px;overflow-y:auto}
430: .slider-row{display:grid;grid-template-columns:120px 1fr 48px;align-items:center;gap:14px;padding:12px 0;border-bottom:1px solid rgba(93,75,45,.12)}
431: .slider-row span{font-size:11px;letter-spacing:.08em;color:#4b3f2e}
432: .slider-row output{font-size:10px;color:#8a795d;text-align:right}
433: input[type=range]{-webkit-appearance:none;appearance:none;height:2px;background:rgba(93,75,45,.25);outline:none}
434: input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:13px;height:13px;border-radius:50%;background:var(--amber-soft);
435:   border:2px solid #efe3cd;box-shadow:0 1px 5px rgba(0,0,0,.3);cursor:pointer}
436: input[type=range]::-moz-range-thumb{width:11px;height:11px;border-radius:50%;background:var(--amber-soft);border:2px solid #efe3cd;cursor:pointer}
437: .toggle-row{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:14px 0;border-bottom:1px solid rgba(93,75,45,.12)}
438: .toggle-row span{font-size:11px;letter-spacing:.08em;color:#4b3f2e}
439: .toggle-row small{display:block;font-size:9px;color:#8a795d;letter-spacing:0;margin-top:2px}
440: .toggle-row input{width:34px;height:18px;appearance:none;-webkit-appearance:none;background:rgba(93,75,45,.2);border-radius:10px;position:relative;cursor:pointer;transition:.2s}
441: .toggle-row input::after{content:"";position:absolute;left:2px;top:2px;width:14px;height:14px;border-radius:50%;background:#efe3cd;transition:.2s}
442: .toggle-row input:checked{background:var(--amber-soft)}
443: .toggle-row input:checked::after{left:18px}
444: .settings-note{margin:22px 0 16px;padding:16px;background:rgba(255,252,242,.3);border:1px solid rgba(93,75,45,.12)}
445: .settings-note p{font-size:11px;line-height:1.55;color:#5d503c}
446: .settings-note strong{color:#332b1f}
447: .settings-credit{margin-top:12px;font-family:var(--serif);font-style:italic;font-size:12px;color:#8a795d !important;line-height:1.45}
448: #fullscreenBtn{color:#6e5d42;border-color:rgba(93,75,45,.3)}
