450: /* howto */
451: .howto-frame{width:min(620px,94vw);max-height:92vh;background:linear-gradient(160deg,#eee1c9,#e0cfb0);border:1px solid rgba(200,164,102,.5);
452:   box-shadow:var(--shadow);overflow:hidden;display:flex;flex-direction:column}
