454: .howto-item{padding:12px 0;border-bottom:1px solid rgba(93,75,45,.12)}
455: .howto-key{display:inline-block;font-size:8.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--gold-dim);margin-bottom:4px}
456: .howto-item p{font-family:var(--serif);font-size:15px;line-height:1.45;color:#4a3f2e}
