458: /* ending */
459: .ending{z-index:45;background:#081012;display:flex;align-items:center;justify-content:center;padding:0}
460: #endingCanvas{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.9}
461: .ending-wash{position:absolute;inset:0;background:linear-gradient(90deg,rgba(5,9,10,.93) 0%,rgba(5,9,10,.72) 44%,rgba(5,9,10,.2) 80%,rgba(5,9,10,.55) 100%)}
462: .ending-card{position:relative;z-index:2;width:min(560px,88vw);margin-right:auto;margin-left:7vw;max-height:92vh;overflow-y:auto;padding:20px 0}
463: .ending-eyebrow{font-size:9px;letter-spacing:.26em;text-transform:uppercase;color:var(--gold)}
464: .ending-card h2{font-size:clamp(42px,5.4vw,68px);line-height:.95;color:#f4ead8;margin:10px 0 20px}
465: .ending-prose p{font-family:var(--serif);font-size:clamp(16px,1.5vw,19px);line-height:1.6;color:#d3c5ae;margin-bottom:12px}
466: .ending-prose p:first-child::first-letter{font-size:2.6em;float:left;line-height:.8;padding:6px 8px 0 0;color:var(--amber)}
467: .ending-quote{font-family:var(--serif);font-style:italic;font-size:16px;line-height:1.5;color:#b8a98f;border-left:1px solid rgba(200,164,102,.4);
468:   padding-left:16px;margin:20px 0 26px}
469: .ending-actions{display:flex;align-items:center;gap:22px;flex-wrap:wrap}
470: .ending-actions .text-btn{color:#a99c86}
471: 
472: /* confirm */
473: .confirm-frame{width:min(420px,90vw);padding:34px;background:linear-gradient(165deg,#1a2423,#0c1415);border:1px solid rgba(200,164,102,.25);
474:   box-shadow:var(--shadow);text-align:center}
475: .confirm-frame h2{font-size:30px;color:#f1e5cf;margin:6px 0 10px}
476: .confirm-frame p{font-family:var(--serif);font-size:16px;line-height:1.5;color:#bcae97}
477: .confirm-actions{display:flex;justify-content:center;gap:18px;margin-top:24px;align-items:center}
478: .confirm-actions .text-btn{color:#9c907b}
479: 
480: /* save pip + fades */
481: .save-pip{position:absolute;right:26px;bottom:22px;font-size:8px;letter-spacing:.2em;text-transform:uppercase;color:#8d826f;
482:   opacity:0;transition:opacity .5s;pointer-events:none;z-index:12}
483: .save-pip.show{opacity:1}
484: .scene-fade{position:absolute;inset:0;background:#060c0d;opacity:0;pointer-events:none;transition:opacity .55s ease;z-index:14}
