490: .cinema-bars i:first-child{top:0}
491: .cinema-bars i:last-child{bottom:0}
492: 
493: /* title flash / chapter card */
494: .chapter-card{position:absolute;inset:0;z-index:16;display:grid;place-items:center;pointer-events:none;opacity:0;transition:opacity 1s}
495: .chapter-card.show{opacity:1}
496: .chapter-card div{text-align:center;padding:30px 50px;position:relative}
497: .chapter-card .cc-eyebrow{font-size:9px;letter-spacing:.3em;text-transform:uppercase;color:var(--gold);margin-bottom:10px}
498: .chapter-card h2{font-size:clamp(34px,5vw,58px);color:#f1e5cf;line-height:1}
499: .chapter-card p{font-family:var(--serif);font-style:italic;font-size:16px;color:#b8ab94;margin-top:10px}
500: .chapter-card div::before,.chapter-card div::after{content:"";position:absolute;left:50%;transform:translateX(-50%);width:44px;height:1px;background:rgba(200,164,102,.5)}
501: .chapter-card div::before{top:0}
502: .chapter-card div::after{bottom:0}
