526:   .hud-actions{gap:4px}
527:   .hud-btn{min-width:42px;padding:7px 6px 6px}
528:   .hud-btn svg{width:18px;height:18px}
529:   .hud-btn span{font-size:6.5px;letter-spacing:.08em}
530:   .hud-under{left:12px;right:12px;bottom:calc(10px + env(safe-area-inset-bottom))}
